import json
from http.server import BaseHTTPRequestHandler, HTTPServer

class H(BaseHTTPRequestHandler):
    def _send(self, code, obj=None):
        b = json.dumps(obj or {}).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)
    def do_POST(self):
        ln = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(ln)
        print("POST", self.path, "ctype:", self.headers.get("Content-Type"), "body:", body.decode(), flush=True)
        if self.path == "/projects/1/tasks":
            try: json.loads(body); self._send(201, {"id": 1})
            except Exception: self._send(400, {"err": "bad json"})
        else:
            self._send(404, {"err": "not found"})
    def do_GET(self):
        print("GET", self.path, "X-Dsl-Example:", self.headers.get("X-Dsl-Example"), flush=True)
        if self.path == "/tasks":
            self._send(200, {"tasks": []})
        else:
            self._send(404, {"err": "not found"})
    def log_message(self, *a): pass

HTTPServer(("127.0.0.1", 9801), H).serve_forever()
EOF
